if (strtoupper((string) ($_SERVER['REQUEST_METHOD'] ?? '')) === 'HEAD') exit;
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Owner Control — Lab Store Drafts</title><style>:root{color-scheme:dark;font-family:system-ui,sans-serif}body{margin:0;background:#111820;color:#f4f7fb;padding:24px}main{max-width:960px;margin:auto}a{color:#f6cc65}.muted{color:#b8c6d2}.grid{display:grid;gap:16px;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));margin:20px 0}.card,form{background:#1b2530;border:1px solid #33404c;border-radius:12px;padding:16px}label{display:block;margin:10px 0 4px}input,textarea,button{box-sizing:border-box;width:100%;padding:9px;border-radius:7px}textarea{min-height:90px}button{margin-top:14px;background:#f6cc65;color:#111820;font-weight:700;border:0}button[disabled]{opacity:.6}#status{min-height:1.5em}.draft{cursor:pointer}.draft h2{margin:0;font-size:1.1rem}.draft p{white-space:pre-wrap}</style></head><body><main><p><a href="/owner-control/v1/index.php">← Owner Control</a></p><h1>Lab Store Drafts</h1><p class="muted">Private draft metadata only. Nothing on this page can publish an offer or affect a player.</p><p id="status" role="status">Loading drafts…</p><section id="list" class="grid" aria-label="Private Lab Store drafts"></section><form id="draft-form" novalidate><h2 id="form-title">Create draft</h2><input id="draft-id" type="hidden"><input id="draft-version" type="hidden"><label>Title <input id="title" maxlength="200" required></label><label>Category <input id="category" maxlength="80" required></label><label>Description <textarea id="description" maxlength="4000" required></textarea></label><label>Public media reference (optional) <input id="media" maxlength="500" placeholder="/public/img/example.png"></label><button id="save" type="submit">Save private draft</button><button id="cancel" type="button" hidden>Cancel edit</button></form></main><script>'use strict';const list=document.getElementById('list'),status=document.getElementById('status'),form=document.getElementById('draft-form'),cancel=document.getElementById('cancel'),save=document.getElementById('save');let pendingSave=null,inFlight=false;const newKey=()=>crypto.randomUUID().replaceAll('-','')+crypto.randomUUID().replaceAll('-','');function text(value){const p=document.createElement('p');p.textContent=value;return p}function basePayload(){const id=Number(document.getElementById('draft-id').value),editing=Number.isInteger(id)&&id>0,payload={title:document.getElementById('title').value,category:document.getElementById('category').value,description:document.getElementById('description').value,media_reference:document.getElementById('media').value||null};if(editing){payload.draft_id=id;payload.expected_version=Number(document.getElementById('draft-version').value)}return payload}function fingerprint(payload){return JSON.stringify(payload)}function pendingKey(payload){const current=fingerprint(payload);if(!pendingSave||pendingSave.fingerprint!==current)pendingSave={fingerprint:current,key:newKey()};return pendingSave.key}function reset(){form.reset();document.getElementById('draft-id').value='';document.getElementById('draft-version').value='';document.getElementById('form-title').textContent='Create draft';cancel.hidden=true;pendingSave=null}function show(items){list.replaceChildren();for(const draft of items){const card=document.createElement('article');card.className='card draft';const heading=document.createElement('h2');heading.textContent=draft.title;card.append(heading,text(draft.category+' · private draft · version '+draft.version),text(draft.description));card.addEventListener('click',()=>{document.getElementById('draft-id').value=draft.draft_id;document.getElementById('draft-version').value=draft.version;document.getElementById('title').value=draft.title;document.getElementById('category').value=draft.category;document.getElementById('description').value=draft.description;document.getElementById('media').value=draft.media_reference||'';document.getElementById('form-title').textContent='Edit private draft';cancel.hidden=false;pendingSave=null;window.scrollTo({top:document.body.scrollHeight,behavior:'smooth'})});list.append(card)}}async function load(){const response=await fetch('/api/owner-control/v1/lab-store/drafts.php',{credentials:'same-origin',cache:'no-store'}),payload=await response.json();if(!response.ok||payload.success!==true||payload.mode!=='draft_only'||payload.writes!==false||!Array.isArray(payload.drafts))throw Error();show(payload.drafts);status.textContent=payload.drafts.length?'Private drafts loaded.':'No private drafts yet.'}async function csrf(action){const response=await fetch('/api/owner-control/v1/lab-store/draft-csrf.php',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json'},body:JSON.stringify({action})}),payload=await response.json();if(!response.ok||payload.success!==true||payload.capability!=='lab_store_drafts_csrf'||typeof payload.csrf_token!=='string')throw Error();return payload.csrf_token}for(const input of form.querySelectorAll('input,textarea'))input.addEventListener('input',()=>{if(pendingSave&&pendingSave.fingerprint!==fingerprint(basePayload()))pendingSave=null});form.addEventListener('submit',async event=>{event.preventDefault();if(inFlight)return;const payload=basePayload(),editing=Object.hasOwn(payload,'draft_id');payload.idempotency_key=pendingKey(payload);inFlight=true;save.disabled=true;try{const action=editing?'update':'create',token=await csrf(action),response=await fetch(editing?'/api/owner-control/v1/lab-store/draft-update.php':'/api/owner-control/v1/lab-store/draft-create.php',{method:'POST',credentials:'same-origin',cache:'no-store',headers:{'Content-Type':'application/json','X-CSRF-Token':token},body:JSON.stringify(payload)}),result=await response.json();if(!response.ok||result.success!==true)throw Error();reset();await load()}catch(_){status.textContent='Draft save is unavailable. Retry without changing fields to reuse the same safe request key.'}finally{inFlight=false;save.disabled=false}});cancel.addEventListener('click',reset);load().catch(()=>{status.textContent='Private drafts are currently unavailable.'});</script></body></html>
